const TAILS = {
  "over20 sectionOrder | 25 sections all missing": { tails: ["5 more section(s) are missing or out of order"], dropped: 5 },
  "over20 sectionOrder | 21 sections all missing": { tails: ["1 more section(s) are missing or out of order"], dropped: 1 },
  "over20 sectionWords | 25 sections all too short": { tails: ["5 more section(s) are outside the range"], dropped: 5 },
  "over20 sectionWords | 25 sections, 22 too long": { tails: ["2 more section(s) are outside the range"], dropped: 2 },
  "over20 sectionWords | 25 sections, 21 too short": { tails: ["1 more section(s) are outside the range"], dropped: 1 },
  "over20 blockLines | 25 blocks each missing 2 words": { tails: ["15 more block(s) are missing a required word"], dropped: 30 },
  "over20 blockLines | 25 blocks, each missing 1 word": { tails: ["5 more block(s) are missing a required word"], dropped: 5 },
  "over20 blockLines | 30 blocks, mixed 0/1/2 missing": { tails: ["6 more block(s) are missing a required word"], dropped: 10 },
  "over20 blockLines | 11 blocks both missing (22 items, cut)": { tails: ["1 more block(s) are missing a required word"], dropped: 2 },
  "over20 blockLines | 25 blocks missing + not multiple (size 2)": { tails: ["16 more block(s) are missing a required word"], dropped: 32 },
  "mixed shape over20 | 25 sections all red in every check": { tails: ["30 more block(s) are missing a required word", "5 more section(s) are outside the range"], dropped: 35 },
  "mixed shape over20 | no headings, long text": { tails: ["5 more section(s) are missing or out of order"], dropped: 5 },
};
const EXTRA_KEYS_ID = 'over20 extra keys | 25 extra keys';

const isTail = (r) => /^\d+ more (section|block)\(s\) /.test(r);

test('am19 parity: the big table covers exactly the cases defined, ids unique', () => {
  assert.equal(FROZEN_BIG.length, bigCases.length);
  assert.deepEqual(bigCases.map((c) => `${c.pair} | ${c.label}`), FROZEN_BIG.map((f) => f.id));
  assert.equal(new Set(FROZEN_BIG.map((f) => f.id)).size, FROZEN_BIG.length);
  for (const id of Object.keys(TAILS)) assert.ok(FROZEN_BIG.some((f) => f.id === id), `TAILS names a real case: ${id}`);
});

test('am19 parity: same verdict and same sentences as before the switch; past 20 only the cut and its "N more" tail differ', async () => {
  for (let i = 0; i < bigCases.length; i++) {
    const c = bigCases[i];
    const f = FROZEN_BIG[i];
    const r = await closeSoftgreen(strip(c.input), c.shape);
    assert.equal(r.verdict, f.verdict, f.id);
    if (f.id === EXTRA_KEYS_ID) {
      // the old sentence listed all 25 keys; the new one lists the first 20 and says 5 more
      assert.equal(r.red, f.red.replace(', "k20", "k21", "k22", "k23", "k24"', ' and 5 more'), f.id);
      assert.deepEqual(r.reds, ['extra key(s): k0, k1, k2, k3, k4, k5, k6, k7, k8, k9, k10, k11, k12, k13, k14, k15, k16, k17, k18, k19 and 5 more']);
      continue;
    }
    const want = TAILS[f.id];
    if (!want) {
      assert.deepEqual({ red: r.red ?? null, reds: r.reds ?? null }, { red: f.red, reds: f.reds }, `${f.id}: no tail, so identical`);
      continue;
    }
    const tails = r.reds.filter(isTail);
    const kept = r.reds.filter((x) => !isTail(x));
    assert.deepEqual(tails, want.tails, `${f.id}: the exact tail sentences`);
    // what is kept is the old list, in order, minus exactly the entries the cut replaced
    let at = 0;
    for (const x of kept) { at = f.reds.indexOf(x, at); assert.ok(at >= 0, `${f.id}: "${x}" is an old sentence, in old order`); at += 1; }
    assert.equal(f.reds.length - kept.length, want.dropped, `${f.id}: entries the cut replaced`);
    assert.equal(r.red, r.reds.join('; '), f.id);
  }
});
